    "  vec2 uv = v_uv;\n"
    "  if (u_tiled != 0) {\n"
    "    uv = fract(v_uv);\n"
    "  }\n"
    "  gl_FragColor = texture2D(u_tex, uv);\n"
    "}\n";


/* ================================================================
 * Dust Shader (depth-based post-process)
 * ================================================================ */

static const char *DUST_VS =
    "attribute vec2 a_pos;\n"
    "attribute vec2 a_uv;\n"
    "uniform vec2 u_screen;\n"
    "varying vec2 v_uv;\n"
    "\n"
    "void main() {\n"
    "  vec2 ndc;\n"
    "  ndc.x = (a_pos.x / u_screen.x) * 2.0 - 1.0;\n"
    "  ndc.y = 1.0 - (a_pos.y / u_screen.y) * 2.0;\n"
    "  gl_Position = vec4(ndc, 0.0, 1.0);\n"
    "  v_uv = a_uv;\n"
    "}\n";

static const char *DUST_FS =
    "precision highp float;\n"
    "\n"
    "varying vec2 v_uv;\n"
    "uniform sampler2D u_color_tex;\n"
    "uniform sampler2D u_depth_tex;\n"
    "uniform vec2 u_texel;\n"
    "uniform vec3 u_dust_color;\n"
    "uniform float u_znear;\n"
    "uniform float u_zfar;\n"
    "uniform float u_start;\n"
    "uniform float u_end;\n"
    "uniform float u_falloff_distance;\n"
    "uniform float u_density;\n"
    "uniform float u_noise_strength;\n"
    "uniform float u_noise_scale;\n"
    "uniform float u_blur_px;\n"
    "uniform float u_time;\n"
    "\n"
    "float decode_depth01(vec4 enc) {\n"
    "  return dot(enc, vec4(1.0, 1.0 / 255.0, 1.0 / 65025.0, 1.0 / 16581375.0));\n"
    "}\n"
    "\n"
    "float hash12(vec2 p) {\n"
    "  vec3 p3 = fract(vec3(p.xyx) * 0.1031);\n"
    "  p3 += dot(p3, p3.yzx + 33.33);\n"
    "  return fract((p3.x + p3.y) * p3.z);\n"
    "}\n"
    "\n"
    "void main() {\n"
    "  vec4 depth_enc = texture2D(u_depth_tex, v_uv);\n"
    "  float depth01 = clamp(decode_depth01(depth_enc), 0.0, 1.0);\n"
    "  float depth = u_znear + depth01 * (u_zfar - u_znear);\n"
    "\n"
    "  float denom = max(u_end - u_start, 0.0001);\n"
    "  if (u_falloff_distance > 0.0) {\n"
    "    denom = max(u_falloff_distance, 0.0001);\n"
    "  }\n"
    "  float fog = smoothstep(0.0, 1.0, clamp((depth - u_start) / denom, 0.0, 1.0));\n"
    "  fog = clamp(fog * max(u_density, 0.0), 0.0, 1.0);\n"
    "\n"
    "  float n = hash12(v_uv * max(u_noise_scale, 0.001) + vec2(u_time * 0.071, u_time * 0.037));\n"
    "  fog = clamp(fog + (n - 0.5) * u_noise_strength, 0.0, 1.0);\n"
    "\n"
    "  vec3 center = texture2D(u_color_tex, v_uv).rgb;\n"
    "  float radius = max(u_blur_px, 0.0) * fog;\n"
    "  vec2 o = u_texel * radius;\n"
    "  vec3 blur = center * 0.40;\n"
    "  blur += texture2D(u_color_tex, v_uv + vec2( o.x, 0.0)).rgb * 0.15;\n"
    "  blur += texture2D(u_color_tex, v_uv + vec2(-o.x, 0.0)).rgb * 0.15;\n"
    "  blur += texture2D(u_color_tex, v_uv + vec2(0.0,  o.y)).rgb * 0.15;\n"
    "  blur += texture2D(u_color_tex, v_uv + vec2(0.0, -o.y)).rgb * 0.15;\n"
    "\n"
    "  gl_FragColor = vec4(mix(blur, u_dust_color, fog), 1.0);\n"
    "}\n";


/* ================================================================
 * Radiation Noise Shader (stochastic channel spikes)
 * ================================================================ */

static const char *RADIATION_VS =
    "attribute vec2 a_pos;\n"
    "attribute vec2 a_uv;\n"
    "uniform vec2 u_screen;\n"
    "varying vec2 v_uv;\n"
    "\n"
    "void main() {\n"
    "  vec2 ndc;\n"
    "  ndc.x = (a_pos.x / u_screen.x) * 2.0 - 1.0;\n"
    "  ndc.y = 1.0 - (a_pos.y / u_screen.y) * 2.0;\n"
    "  gl_Position = vec4(ndc, 0.0, 1.0);\n"
    "  v_uv = a_uv;\n"
    "}\n";

static const char *RADIATION_FS =
    "precision highp float;\n"
    "\n"
    "varying vec2 v_uv;\n"
    "uniform sampler2D u_tex;\n"
    "uniform float u_density;\n"
    "uniform float u_min_value;\n"
    "uniform float u_max_value;\n"
    "uniform float u_seed;\n"
    "uniform int u_overlay;\n"
    "\n"
    "float hash12(vec2 p) {\n"
    "  vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.11369, 0.13787));\n"
    "  p3 += dot(p3, p3.yzx + 19.19);\n"
    "  return fract((p3.x + p3.y) * p3.z);\n"
    "}\n"
    "\n"
    "float hash12_wide(vec2 p) {\n"
    "  float a = hash12(p);\n"
    "  float b = hash12(p + vec2(a * 37.17 + 11.13, a * 19.91 + 73.73));\n"
    "  return fract(a + b * 0.61803398875);\n"
    "}\n"
    "\n"
    "void main() {\n"
    "  vec4 src = vec4(0.0, 0.0, 0.0, 0.0);\n"
    "  if (u_overlay == 0) {\n"
    "    src = texture2D(u_tex, v_uv);\n"
    "  }\n"
    "  float density = clamp(u_density, 0.0, 1.0);\n"
    "  float min_value = clamp(min(u_min_value, u_max_value), 0.0, 1.0);\n"
    "  float max_value = clamp(max(u_min_value, u_max_value), 0.0, 1.0);\n"
    "\n"
    "  vec2 seed_jitter = vec2(\n"
    "    hash12(vec2(u_seed, 17.17)),\n"
    "    hash12(vec2(91.31, u_seed))) * 4096.0;\n"
    "  vec2 p = gl_FragCoord.xy + seed_jitter;\n"
    "  float hit = hash12_wide(p);\n"
    "  if (hit < density) {\n"
    "    float channel = hash12_wide(p + vec2(19.19, 73.73));\n"
    "    float elevated = mix(min_value, max_value, hash12_wide(p + vec2(41.41, 11.11)));\n"
    "    if (channel < 0.333333) {\n"
    "      src.r = max(src.r, elevated);\n"
    "    } else if (channel < 0.666667) {\n"
    "      src.g = max(src.g, elevated);\n"
    "    } else {\n"
    "      src.b = max(src.b, elevated);\n"
    "    }\n"
    "    if (u_overlay != 0) {\n"
    "      src.a = 0.75;\n"
    "    }\n"
    "  }\n"
    "\n"
    "  gl_FragColor = vec4(src.rgb, u_overlay != 0 ? src.a : 1.0);\n"
    "}\n";


/* ================================================================
 * Laser Glare Shader (blinding radial glare)
 * ================================================================ */

static const char *LASER_GLARE_VS =
    "attribute vec2 a_pos;\n"
    "attribute vec2 a_uv;\n"
    "uniform vec2 u_screen;\n"
    "varying vec2 v_uv;\n"
    "\n"
    "void main() {\n"
    "  vec2 ndc;\n"
    "  ndc.x = (a_pos.x / u_screen.x) * 2.0 - 1.0;\n"
    "  ndc.y = 1.0 - (a_pos.y / u_screen.y) * 2.0;\n"
    "  gl_Position = vec4(ndc, 0.0, 1.0);\n"
    "  v_uv = a_uv;\n"
    "}\n";

static const char *LASER_GLARE_FS =
    "precision highp float;\n"
    "\n"
    "varying vec2 v_uv;\n"
    "uniform sampler2D u_tex;\n"
    "uniform vec2 u_screen;\n"
    "uniform vec2 u_center;\n"
    "uniform float u_radius;\n"
    "uniform float u_decay;\n"
    "uniform float u_hot_radius;\n"
    "uniform float u_hot_strength;\n"
    "uniform float u_glare_strength;\n"
    "uniform float u_streak_strength;\n"
    "\n"
    "void main() {\n"
    "  vec3 src = texture2D(u_tex, v_uv).rgb;\n"
    "  float radius = clamp(u_radius, 0.0, 1.0);\n"
    "  if (radius >= 0.999) {\n"
    "    gl_FragColor = vec4(1.0, 1.0, 1.0, 1.0);\n"
    "    return;\n"
    "  }\n"
    "\n"
    "  vec2 center = clamp(u_center, 0.0, 1.0);\n"
    "  vec2 delta_px = (v_uv - center) * u_screen;\n"
    "  float d = length(delta_px);\n"
    "  float radius_px = max(1.0, radius * 0.5 * length(u_screen));\n"
    "  float decay = max(u_decay, 0.001);\n"
    "\n"
    "  float norm_d = clamp(d / radius_px, 0.0, 1.0);\n"
    "  float glare = pow(1.0 - norm_d, decay) * max(u_glare_strength, 0.0);\n"
    "\n"
    "  float hot_px = max(1.0, radius_px * clamp(u_hot_radius, 0.0, 1.0));\n"
    "  float hot = smoothstep(hot_px, 0.0, d) * max(u_hot_strength, 0.0);\n"
    "\n"
    "  float x_dist = abs(delta_px.x);\n"
    "  float y_dist = abs(delta_px.y);\n"
    "  float axis_width = max(1.0, radius_px * 0.035);\n"
    "  float axis_fade_x = pow(1.0 - clamp(x_dist / radius_px, 0.0, 1.0), decay * 0.55);\n"
    "  float axis_fade_y = pow(1.0 - clamp(y_dist / radius_px, 0.0, 1.0), decay * 0.55);\n"
    "  float h_streak = exp(-y_dist / axis_width) * axis_fade_x;\n"
    "  float v_streak = exp(-x_dist / axis_width) * axis_fade_y;\n"
    "\n"
    "  float diag_a = abs(delta_px.x - delta_px.y);\n"
    "  float diag_b = abs(delta_px.x + delta_px.y);\n"
    "  float diag_fade = pow(1.0 - norm_d, decay * 0.75);\n"
    "  float diag_streak = (exp(-diag_a / (axis_width * 1.6)) +\n"
    "                       exp(-diag_b / (axis_width * 1.6))) * 0.35 * diag_fade;\n"
    "\n"
    "  float streak = (h_streak + v_streak + diag_streak) * max(u_streak_strength, 0.0);\n"
    "  float intensity = clamp(max(hot, glare + streak), 0.0, 1.0);\n"
    "  gl_FragColor = vec4(mix(src, vec3(1.0), intensity), 1.0);\n"
    "}\n";

#endif /* POLLYN_SHADERS_H */
